SELECT * FROM tb_agent_commission_stats 
WHERE statistics_date = #{statisticsDate}
ORDER BY agent_id, salesman_id

SELECT * FROM tb_agent_commission_stats 
WHERE agent_id = #{agentId}

    AND statistics_date >= #{startDate}


    AND statistics_date <= #{endDate}

ORDER BY statistics_date DESC, salesman_id

SELECT * FROM tb_agent_commission_stats 
WHERE salesman_id = #{salesmanId}

    AND statistics_date >= #{startDate}


    AND statistics_date <= #{endDate}

ORDER BY statistics_date DESC

SELECT * FROM tb_agent_commission_stats 
WHERE statistics_date BETWEEN #{startDate} AND #{endDate}
ORDER BY statistics_date DESC, agent_id, salesman_id

SELECT COALESCE(SUM(commission_amount), 0) 
FROM tb_agent_commission_stats 
WHERE statistics_date = #{statisticsDate}

SELECT COALESCE(SUM(commission_amount), 0) 
FROM tb_agent_commission_stats 
WHERE statistics_date BETWEEN #{startDate} AND #{endDate}

SELECT COUNT(*) 
FROM tb_agent_commission_stats 
WHERE agent_id = #{agentId} 
AND salesman_id = #{salesmanId} 
AND statistics_date = #{statisticsDate}

